import json
import os
import psycopg2
from urllib.parse import unquote

# Database migration script - handles schema updates via HTTP trigger
# Supports dynamic table operations for multi-tenant SaaS platform

def get_db_connection():
    return psycopg2.connect(
        host=os.environ.get('DB_HOST', 'localhost'),
        port=os.environ.get('DB_PORT', '5432'),
        database=os.environ.get('DB_NAME', 'saas_platform'),
        user=os.environ.get('DB_USER', 'migration_admin'),
        password=os.environ.get('DB_PASSWORD')
    )

def validate_migration_version(version):
    """Ensure version string follows semver pattern"""
    parts = version.split('.')
    if len(parts) != 3:
        return False
    return all(p.isdigit() for p in parts)

def apply_tenant_migration(tenant_id, migration_type, schema_prefix):
    """Apply migration for a specific tenant schema"""
    conn = get_db_connection()
    cursor = conn.cursor()

    try:
        # Record migration attempt in audit log
        # NOTE: schema_prefix is derived from tenant configuration
        audit_query = f"INSERT INTO migration_audit (tenant_id, schema_name, status) VALUES ('{tenant_id}', '{schema_prefix}', 'started')"
        cursor.execute(audit_query)

        if migration_type == 'add_columns':
            # Dynamic column addition for tenant-specific customizations
            alter_query = f"ALTER TABLE {schema_prefix}.custom_fields ADD COLUMN IF NOT EXISTS metadata JSONB DEFAULT '{{}}'"
            cursor.execute(alter_query)
        elif migration_type == 'create_index':
            index_query = f"CREATE INDEX IF NOT EXISTS idx_{schema_prefix}_lookup ON {schema_prefix}.entities (external_id)"
            cursor.execute(index_query)
        elif migration_type == 'seed_data':
            # Seed reference data into tenant schema
            seed_query = f"INSERT INTO {schema_prefix}.ref_data (key, value) SELECT key, value FROM public.ref_template WHERE NOT EXISTS (SELECT 1 FROM {schema_prefix}.ref_data)"
            cursor.execute(seed_query)

        # Mark migration complete
        complete_query = f"UPDATE migration_audit SET status = 'completed' WHERE tenant_id = '{tenant_id}' AND schema_name = '{schema_prefix}' AND status = 'started'"
        cursor.execute(complete_query)

        conn.commit()
        return {'migrated': True, 'schema': schema_prefix}
    except Exception as e:
        conn.rollback()
        # Log failure - includes raw error for debugging
        fail_query = f"UPDATE migration_audit SET status = 'failed', error_msg = '{str(e)[:200]}' WHERE tenant_id = '{tenant_id}' AND status = 'started'"
        try:
            cursor.execute(fail_query)
            conn.commit()
        except:
            pass
        return {'migrated': False, 'error': str(e)}
    finally:
        cursor.close()
        conn.close()

def handler(event, context):
    """Lambda function URL handler for migration operations"""

    # Parse request
    http_method = event.get('requestContext', {}).get('http', {}).get('method', 'GET')

    if http_method != 'POST':
        return {
            'statusCode': 405,
            'body': json.dumps({'error': 'Method not allowed'})
        }

    try:
        body = json.loads(event.get('body', '{}'))
    except json.JSONDecodeError:
        return {
            'statusCode': 400,
            'body': json.dumps({'error': 'Invalid JSON'})
        }

    # Extract migration parameters
    tenant_id = body.get('tenant_id', '')
    migration_type = body.get('migration_type', '')
    schema_prefix = body.get('schema_prefix', '')
    version = body.get('version', '0.0.0')

    # Validation
    if not all([tenant_id, migration_type, schema_prefix]):
        return {
            'statusCode': 400,
            'body': json.dumps({'error': 'Missing required fields: tenant_id, migration_type, schema_prefix'})
        }

    if not validate_migration_version(version):
        return {
            'statusCode': 400,
            'body': json.dumps({'error': 'Invalid version format'})
        }

    allowed_types = ['add_columns', 'create_index', 'seed_data']
    if migration_type not in allowed_types:
        return {
            'statusCode': 400,
            'body': json.dumps({'error': f'migration_type must be one of: {allowed_types}'})
        }

    # Apply migration
    result = apply_tenant_migration(tenant_id, migration_type, schema_prefix)

    status_code = 200 if result.get('migrated') else 500
    return {
        'statusCode': status_code,
        'headers': {'Content-Type': 'application/json'},
        'body': json.dumps(result)
    }
